import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { useState } from 'react';

export const useResumeScanner = () => {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);

  const scanResume = async (file: File, jobDescription: string) => {
    setLoading(true);
    const formData = new FormData();
    formData.append('resume', file);
    formData.append('description', jobDescription);

    try {
      const response = await fetch('/api/scan', { method: 'POST', body: formData });
      const data = await response.json();
      setResult(data);
    } finally {
      setLoading(false);
    }
  };

  return { scanResume, loading, result };
};

import React from 'react';

interface GaugeProps { score: number }

export const MatchScoreGauge: React.FC<GaugeProps> = ({ score }) => {
  const radius = 40;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (score / 100) * circumference;

  return (
    <div className="relative w-32 h-32">
      <svg className="w-full h-full transform -rotate-90">
        <circle cx="64" cy="64" r={radius} className="stroke-gray-200 fill-none" strokeWidth="8" />
        <circle 
          cx="64" cy="64" r={radius} 
          className="stroke-blue-600 fill-none transition-all duration-1000 ease-out"
          strokeWidth="8"
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap="round"
        />
      </svg>
      <span className="absolute inset-0 flex items-center justify-center font-bold text-xl">{score}%</span>
    </div>
  );
};
